<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {usePlanning,api,post,put} from './store'
import type {Code,Employee,Day,RequestRow,Job} from './types'
import ScheduleGrid from './components/ScheduleGrid.vue'
const store=usePlanning(),route=useRoute(),router=useRouter()
const overlay=ref(true),group=ref(''),search=ref(''),versionId=ref(''),compareId=ref(''),comparison=ref<any>(),viewMode=ref('all')
const edits=ref<Record<string,Code>>({}),undo=ref<Record<string,Code>[]>([]),redo=ref<Record<string,Code>[]>([])
const cell=ref<{employee:Employee;day:Day}>(),cellCode=ref<Code>('OFF'),cellDialog=ref(false)
const requestDialog=ref(false),requestRows=ref<RequestRow[]>([]),prefs=ref<any[]>([]),allEmployees=ref<Employee[]>([])
const requestForm=reactive({employee_ids:[] as number[],from_date:'',to_date:'',code:'DT' as Code,reason:'',status:'APPROVED',replace_ids:[] as string[]})
const preferenceForm=reactive({employee_id:undefined as number|undefined,day:'',kind:'PREFER_OFF',shift:undefined as number|undefined,weight:1})
const requestTab=ref('hard'),requestFilter=ref('')
const jobDialog=ref(false),jobMode=ref('REPAIR'),jobForm=reactive({budget:60,passes:3,repair_mode:'FAST',as_of:'',allowed_from:'',allowed_until:'',max_changes:undefined as number|undefined,no_admin_increase:false,no_overtime_increase:false,request_ids:[] as string[]})
const freshHelp='Xếp lại toàn bộ tháng từ đầu theo mọi yêu cầu BKD, CT, DT, OFF và ca cố định đã duyệt. Các yêu cầu cũ chưa hủy vẫn có hiệu lực. Lịch cũ giữ trong lịch sử; kết quả mới là bản nháp, chỉ thay lịch áp dụng khi bạn duyệt.'
const jobDetail=ref<Job>(),jobLogDialog=ref(false),validation=ref<any>(),validationDialog=ref(false)
const rules=ref<any>(),rulesForm=ref<any>({}),holidayText=ref(''),demandRows=ref<any[]>([]),assumptions=ref(''),inputConfirmed=ref(false)
const workTimeDialog=ref(false),workTimeRest=ref<number>(),workTimes=reactive([{code:'CT',start:'',end:''},{code:'DT',start:'',end:''},{code:'T',start:'',end:''}])
const employeesDialog=ref(false),employeeForm=reactive({id:1,name:'',group:'SHIFT',is_leader:false,allowed_shifts:[1,2,3],target_credit:null as number|null})
const plans=ref<any[]>([]),planId=ref<number>(),annual=ref<any>(),annualEmployee=ref<number>(),annualDialog=ref(false)
const annualForm=reactive({year:2027,name:'Kế hoạch năm 2027',assumptions:'Dự kiến theo nhân sự và quyền ca tháng nguồn. Chưa xác nhận ngày lễ và yêu cầu trong tương lai.'})
const audit=ref<any[]>([]),importDialog=ref(false),importForm=reactive({excel:'input/input.xlsx',rules:'config/rules.json',schedule:'',dry_run:true}),importResult=ref<any>()
let interval:ReturnType<typeof setInterval>|undefined
const busyJob=computed(()=>store.jobs.find(j=>['QUEUED','RUNNING','CANCELLING'].includes(j.status)))
const lastJob=computed(()=>store.jobs[0])
const changed=computed(()=>new Set<string>((comparison.value?.changes??[]).map((x:any)=>`${x.employee_id}|${x.day}`)))
const reference=computed(()=>{if(!comparison.value||!store.calendar)return undefined;const out=Object.fromEntries(store.calendar.assignments.map(a=>[`${a.employee_id}|${a.day}`,a.code]));for(const c of comparison.value.changes)out[`${c.employee_id}|${c.day}`]=c.before;return out})
const pendingRequests=computed(()=>store.calendar?.requests.filter(r=>r.status==='APPROVED')??[])
const repairChoices=computed(()=>[...(store.calendar?.requests.filter(r=>['APPROVED','APPLIED'].includes(r.status))??[]),...(store.calendar?.cancelled_requests??[])])
const selectedVersion=computed(()=>store.calendar?.version)
const unsaved=computed(()=>Object.keys(edits.value).length)
const versionLabel=(v:any)=>`${v.status} · ${v.source} · ${v.id.slice(0,8)}`
const employeeName=(id:number)=>store.calendar?.employees.find(e=>e.id===id)?.name??allEmployees.value.find(e=>e.id===id)?.name??String(id)
const dayToday=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Bangkok'})
const localNow=()=>new Date(Date.now()+7*3600000).toISOString().slice(0,16)
async function act(action:()=>Promise<any>,success?:string){try{const r=await action();if(success)ElMessage.success(success);return r}catch(e){store.error=String(e);ElMessage.error(String(e));return null}}
async function refresh(v?:string){await store.refresh(v);versionId.value=store.calendar?.version?.id??'';edits.value={};undo.value=[];redo.value=[];await extras()}
async function extras(){
 const path=route.path
 if(path==='/requests'){[requestRows.value,prefs.value]=await Promise.all([api<RequestRow[]>('/requests'),api('/preferences')])}
 if(path==='/employees')allEmployees.value=await api('/employees')
 if(path==='/rules'&&store.monthId){rules.value=await api(`/months/${store.monthId}/rules`);rulesForm.value={...rules.value.profile.rules,...rules.value.profile.rules.optimization};holidayText.value=store.calendar?.days.filter(d=>d.holiday).map(d=>d.date).join('\n')??'';demandRows.value=store.calendar?.demands.map(d=>({...d}))??[];assumptions.value=store.calendar?.month.assumptions??'';inputConfirmed.value=store.calendar?.month.input_confirmed??false}
 if(path==='/annual'){plans.value=await api('/annual-plans');if(!planId.value&&plans.value.length)planId.value=plans.value[0].id;if(planId.value)annual.value=await api(`/annual-plans/${planId.value}`)}
 if(path==='/history')audit.value=await api('/audit')
}
async function changeMonth(){comparison.value=undefined;compareId.value='';await refresh()}
async function selectVersion(){await refresh(versionId.value||undefined);await compare()}
async function compare(){if(compareId.value&&versionId.value&&compareId.value!==versionId.value)comparison.value=await act(()=>api(`/versions/compare?left=${compareId.value}&right=${versionId.value}`));else comparison.value=undefined}
function showCell(employee:Employee,day:Day){cell.value={employee,day};cellCode.value=edits.value[`${employee.id}|${day.date}`]??store.calendar?.assignments.find(a=>a.employee_id===employee.id&&a.day===day.date)?.code??'OFF';cellDialog.value=true}
function editCell(){if(!cell.value)return;undo.value.push({...edits.value});redo.value=[];edits.value={...edits.value,[`${cell.value.employee.id}|${cell.value.day.date}`]:cellCode.value};cellDialog.value=false}
function undoEdit(){const old=undo.value.pop();if(old){redo.value.push({...edits.value});edits.value=old}}
function redoEdit(){const next=redo.value.pop();if(next){undo.value.push({...edits.value});edits.value=next}}
async function saveEdits(){const body=Object.entries(edits.value).map(([key,code])=>{const [id,day]=key.split('|');return {employee_id:Number(id),day,code}});const r=await act(()=>post(`/versions/${versionId.value}/edit`,{revision:store.revision,edits:body}),'Đã lưu phiên bản nháp mới');if(r)await refresh(r.version_id)}
function newRequest(id?:number,day?:string){requestForm.employee_ids=id?[id]:[];requestForm.from_date=day??store.calendar?.days[0].date??dayToday();requestForm.to_date=requestForm.from_date;requestForm.code='DT';requestForm.reason='';requestForm.replace_ids=[];requestDialog.value=true}
async function saveRequest(){const r=await act(()=>post('/requests/batch',{...requestForm,revision:store.revision}),'Đã lưu yêu cầu. Overlay đã cập nhật; ca cũ vẫn giữ nguyên.');if(r){requestDialog.value=false;await refresh(versionId.value)}}
async function transition(r:RequestRow,status:string){const x=await act(()=>post(`/requests/${r.id}/status`,{revision:store.revision,request_revision:r.revision,status}),'Đã cập nhật trạng thái yêu cầu');if(x)await refresh(versionId.value)}
async function savePreference(){const r=await act(()=>put('/preferences',{...preferenceForm,shift:['PREFER_SHIFT','AVOID_SHIFT'].includes(preferenceForm.kind)?preferenceForm.shift:null,revision:store.revision}),'Đã lưu nguyện vọng mềm');if(r)await refresh(versionId.value)}
function openJob(mode:string){jobMode.value=mode;jobForm.as_of=localNow();jobForm.allowed_from=store.calendar?.days[0].date??'';jobForm.allowed_until=store.calendar?.days.at(-1)?.date??'';jobForm.request_ids=pendingRequests.value.map(r=>r.id);jobDialog.value=true}
async function runJob(){const body:any={revision:store.revision,mode:jobMode.value,month_id:store.monthId,budget:jobForm.budget,passes:jobMode.value==='RESUME'?jobForm.passes:1};if(jobMode.value==='ANNUAL'){body.annual_plan_id=planId.value;body.month_id=null}else if(jobMode.value!=='FRESH')body.baseline_version_id=versionId.value;if(jobMode.value==='REPAIR')Object.assign(body,{request_ids:jobForm.request_ids,as_of:jobForm.as_of+':00+07:00',repair_mode:jobForm.repair_mode,allowed_from:jobForm.allowed_from||null,allowed_until:jobForm.allowed_until||null,max_changes:jobForm.max_changes??null,no_admin_increase:jobForm.no_admin_increase,no_overtime_increase:jobForm.no_overtime_increase});const r=await act(()=>post<Job>('/jobs',body),'Đã gửi job Solver');if(r){jobDialog.value=false;store.jobs.unshift(r);jobDetail.value=r}}
async function viewResult(j:Job){jobDetail.value=j;if(j.result?.version_ids?.length===1){await refresh(j.result.version_ids[0]);compareId.value=store.calendar?.version?.parent_version_id??'';await compare();router.push('/')}else{jobLogDialog.value=true}}
async function confirmVersion(status='PLANNED'){const r=await act(()=>post(`/versions/${versionId.value}/confirm`,{revision:store.revision,expected_current_version_id:store.calendar?.month.current_version_id??null,status}),'Đã duyệt phiên bản');if(r)await refresh(versionId.value)}
async function validate(){validation.value=await act(()=>post(`/versions/${versionId.value}/validate`,{}));if(validation.value)validationDialog.value=true}
async function lockCell(locked:boolean){if(!cell.value)return;const r=await act(()=>put('/locks',{revision:store.revision,month_id:store.monthId,employee_ids:[cell.value!.employee.id],day:cell.value!.day.date,reason:'Khóa bởi quản trị viên',locked}),'Đã cập nhật khóa');if(r){cellDialog.value=false;await refresh(versionId.value)}}
function editEmployee(e?:Employee){Object.assign(employeeForm,e?{...e,allowed_shifts:[...e.allowed_shifts]}:{id:Math.max(0,...(store.calendar?.employees.map(e=>e.id)??[]))+1,name:'',group:'SHIFT',is_leader:false,allowed_shifts:[1,2,3],target_credit:null});employeesDialog.value=true}
async function saveEmployee(){const r=await act(()=>put('/employees',{...employeeForm,revision:store.revision,month_ids:[store.monthId]}),'Đã cập nhật nhân sự cho tháng đang chọn');if(r){employeesDialog.value=false;await refresh(versionId.value)}}
const hardRuleKeys=['max_consecutive_night_shifts','max_consecutive_shift_days','min_rest_hours','min_leaders_per_shift','min_previous_day_staff']
const softRuleKeys=['balance_shift_types','balance_night_shifts','balance_holiday_shifts','balance_weekend_shifts','balance_rest_days','minimize_shift_changes','honor_preferences']
const ruleNames:Record<string,string>={max_consecutive_night_shifts:'Số ca đêm liên tiếp tối đa',max_consecutive_shift_days:'Số ngày trực liên tiếp tối đa',min_rest_hours:'Giờ nghỉ tối thiểu giữa các ca trực',min_leaders_per_shift:'Số phụ trách tối thiểu mỗi ca',min_previous_day_staff:'Số người nối tiếp ngày trước',balance_shift_types:'E01 · Cân bằng loại ca',balance_night_shifts:'E02 · Cân bằng ca đêm',balance_holiday_shifts:'E03a · Cân bằng trực lễ',balance_weekend_shifts:'E03b · Cân bằng trực cuối tuần',balance_rest_days:'E04 · Phân bố ngày nghỉ',minimize_shift_changes:'E05 · Luân phiên linh hoạt',honor_preferences:'E06 · Nguyện vọng mềm'}
async function saveRules(){const body:any={revision:store.revision};for(const k of [...hardRuleKeys,...softRuleKeys])body[k]=rulesForm.value[k];const r=await act(()=>put(`/months/${store.monthId}/rules`,body),'Đã tạo revision cấu hình mới');if(r)await refresh(versionId.value)}
async function saveCalendar(){const r=await act(()=>put(`/months/${store.monthId}/configuration`,{revision:store.revision,holidays:holidayText.value.split(/[\n,]+/).map(d=>d.trim()).filter(Boolean),demands:demandRows.value,input_confirmed:inputConfirmed.value,assumptions:assumptions.value}),'Đã lưu cấu hình tháng');if(r)await refresh(versionId.value)}
async function saveWorkTimes(){const codes:any={BKD:{kind:'rest'}};for(const row of workTimes)codes[row.code]=row.start&&row.end?{kind:'work',start:row.start,end:row.end}:null;const r=await act(()=>put(`/months/${store.monthId}/validation-work-policy`,{revision:store.revision,policy:{min_rest_hours:workTimeRest.value,codes}}),'Đã lưu chính sách kiểm tra giờ phi ca; cần chạy lại và duyệt theo revision mới');if(r){workTimeDialog.value=false;await refresh(versionId.value)}}
async function createAnnual(){const r=await act(()=>post('/annual-plans',{revision:store.revision,...annualForm,source_month_id:store.monthId,months:Array.from({length:12},(_,i)=>i+1)}),'Đã tạo đầu vào 12 tháng với giả định đã khai báo');if(r){annualDialog.value=false;planId.value=r.plan.id;await refresh()}}
async function acceptAnnual(j:Job){const r=await act(()=>post(`/annual-plans/${j.options.annual_plan_id}/confirm`,{revision:store.revision,version_ids:j.result.version_ids}),'Đã xác nhận V0 bất biến cho toàn kế hoạch');if(r){jobLogDialog.value=false;await refresh()}}
async function importLegacy(){importResult.value=await act(()=>post('/import',{...importForm,schedule:importForm.schedule||null}));if(importResult.value&&!importForm.dry_run)await refresh()}
watch(()=>route.path,()=>act(extras))
onMounted(async()=>{await refresh();interval=setInterval(async()=>{const jobs=await act(()=>api<Job[]>('/jobs'));if(jobs){const old=store.jobs[0];store.jobs=jobs;if(jobDetail.value)jobDetail.value=jobs.find((j:Job)=>j.id===jobDetail.value?.id);if(old&&['QUEUED','RUNNING','CANCELLING'].includes(old.status)&&jobs[0]?.status==='SUCCEEDED')ElMessage.success('Solver đã hoàn tất. Mở kết quả để xem và duyệt.')}},1500)})
onUnmounted(()=>{if(interval)clearInterval(interval)})
</script>
<template>
<div class="app-shell">
 <aside class="sidebar"><div class="brand"><div class="brand-mark">A</div><div>AutoShift <small>5.0 · QUẢN LÝ LỊCH TRỰC</small></div></div><nav><router-link to="/">▦ <span>Lịch trực</span></router-link><router-link to="/requests">☷ <span>Yêu cầu & nguyện vọng</span><b v-if="pendingRequests.length">{{pendingRequests.length}}</b></router-link><router-link to="/annual">▤ <span>Kế hoạch năm</span></router-link><router-link to="/employees">♙ <span>Nhân sự</span></router-link><router-link to="/rules">⚙ <span>Cấu hình & quy tắc</span></router-link><router-link to="/history">◷ <span>Lịch sử & kiểm tra</span></router-link></nav><div class="sidebar-bottom"><span class="local-indicator"></span>Chạy tại localhost<small>SQLite · revision {{store.revision}}</small><a href="/docs" target="_blank">Tài liệu API</a><button class="text-button" @click="importDialog=true">Import dữ liệu cũ</button></div></aside>
 <main>
 <header class="topbar"><div><h1>{{({'/':'Lịch trực','/requests':'Yêu cầu & nguyện vọng','/annual':'Kế hoạch năm','/employees':'Nhân sự','/rules':'Cấu hình & quy tắc','/history':'Lịch sử & kiểm tra'} as Record<string,string>)[route.path]??'AutoShift'}}</h1><p>Lập lịch ổn định · Theo dõi thay đổi · Duyệt trước khi áp dụng</p></div><div class="topbar-controls"><label>Tháng làm việc<el-select v-model="store.monthId" @change="changeMonth" style="width:155px"><el-option v-for="m in store.months" :key="m.id" :value="m.id" :label="`${String(m.month).padStart(2,'0')}/${m.year}`" /></el-select></label><el-button @click="refresh(versionId||undefined)" :loading="store.busy">Tải lại</el-button></div></header>
 <div v-if="store.error" class="error-banner" role="alert"><span>{{store.error}}</span><button @click="store.error=''">Đóng</button></div>
 <div v-if="store.calendar" class="notice"><strong>{{store.calendar.validation?.verdict??'CHƯA CÓ LỊCH'}}</strong><span v-if="store.calendar.history_gaps">Thiếu {{store.calendar.history_gaps}} ô lịch sử cho cửa sổ E05.</span><span v-if="store.calendar.validation?.hard_pending?.length">Giờ CT/DT/T chưa được kiểm tra đầy đủ. Lịch dự kiến; chưa đủ điều kiện công bố.</span><span v-if="!store.calendar.month.input_confirmed">Dữ liệu đầu vào chưa xác nhận.</span></div>
 <section v-if="busyJob||lastJob" class="job-strip"><div><span class="status-tag" :class="(busyJob??lastJob)?.status">{{(busyJob??lastJob)?.status}}</span><strong>{{(busyJob??lastJob)?.mode}}</strong><span>{{(busyJob??lastJob)?.stage}}</span></div><div><el-button size="small" @click="jobDetail=busyJob??lastJob;jobLogDialog=true">Theo dõi / log</el-button><el-button v-if="busyJob" size="small" @click="act(()=>post(`/jobs/${busyJob!.id}/cancel`,{}),'Đã yêu cầu hủy')">Hủy job</el-button><el-button v-if="lastJob?.status==='SUCCEEDED'" size="small" type="primary" @click="viewResult(lastJob)">Xem kết quả</el-button></div></section>
 <template v-if="route.path==='/'">
 <section class="workspace-toolbar"><div class="toolbar-row"><label>Phiên bản<el-select v-model="versionId" style="width:295px" @change="selectVersion"><el-option v-for="v in store.calendar?.versions" :key="v.id" :value="v.id" :label="versionLabel(v)" /></el-select></label><el-button @click="openJob('FRESH')" :disabled="!!busyJob">Lập lịch mới</el-button><el-button @click="openJob('RESUME')" :disabled="!versionId||!!busyJob">Tối ưu tiếp</el-button><el-button type="primary" @click="openJob('REPAIR')" :disabled="!versionId||!!busyJob">Điều chỉnh REPAIR</el-button><el-button @click="validate" :disabled="!versionId">Kiểm tra</el-button><a v-if="versionId" :href="`/api/versions/${versionId}/export`" class="download-button">Xuất Excel</a></div>
 <div class="toolbar-row filters"><el-select v-model="group" style="width:150px"><el-option value="" label="Tất cả nhóm"/><el-option value="SHIFT" label="Nhân sự đi ca"/><el-option value="ADMIN" label="Hành chính"/></el-select><el-input v-model="search" placeholder="Tìm ID, họ tên…" clearable style="width:200px"/><el-checkbox v-model="overlay">Hiện yêu cầu chờ áp dụng</el-checkbox><div class="legend"><span class="code-1">1 · Đêm</span><span class="code-2">2 · Sáng</span><span class="code-3">3 · Chiều</span><span>Trống = OFF</span><span>· = Chưa xếp</span></div><el-button size="small" @click="newRequest()">Thêm yêu cầu</el-button></div></section>
 <section v-if="comparison" class="repair-summary"><div><strong>{{comparison.changed_cells}} ô thay đổi</strong><span>{{comparison.after.repair?.affected_people??new Set(comparison.changes.map((c:any)=>c.employee_id)).size}} nhân sự ảnh hưởng</span><span>Giữ nguyên {{((comparison.after.repair?.unchanged_ratio??(1-comparison.changed_cells/(store.calendar?.assignments.length||1)))*100).toFixed(1)}}%</span><span>{{selectedVersion?.proof?.r1_global_optimal?'R1 đã chứng minh toàn phạm vi':'Chưa chứng minh R1 tối ưu toàn cục'}}</span></div><div class="vector" v-if="comparison.after.repair">R1–R7: {{JSON.stringify(comparison.after.repair.vector.slice(0,7))}}<span>Nghỉ ngắn mới: {{comparison.after.repair.new_short_rest}} · ADMIN: {{comparison.after.repair.admin_before}} / {{comparison.after.repair.admin_after}}</span></div><el-radio-group v-model="viewMode" size="small"><el-radio-button value="all">Toàn bộ lịch</el-radio-button><el-radio-button value="affected">Chỉ ô ảnh hưởng</el-radio-button><el-radio-button value="compare">Cũ / mới</el-radio-button></el-radio-group></section>
 <section v-if="store.calendar" class="schedule-panel"><div class="schedule-caption"><span><strong>THÁNG {{store.calendar.month.month}}/{{store.calendar.month.year}}</strong> · {{store.calendar.employees.length}} nhân sự · {{selectedVersion?.status??'Đầu vào chưa xếp lịch'}}</span><div><el-select v-model="compareId" clearable placeholder="So sánh với phiên bản…" style="width:290px" @change="compare"><el-option v-for="v in store.calendar.versions.filter(v=>v.id!==versionId)" :key="v.id" :value="v.id" :label="versionLabel(v)"/></el-select></div></div>
 <ScheduleGrid :data="store.calendar" :overlay="overlay" :group="group" :search="search" :edits="edits" :changed="changed" :affected-only="viewMode==='affected'" :reference="viewMode==='compare'?reference:undefined" @cell="showCell" />
 <div class="schedule-bottom"><span>Nhấp vào ô để xem mã gốc, yêu cầu, trạng thái và khóa.</span><div v-if="unsaved"><span>{{unsaved}} ô chưa lưu</span><el-button size="small" @click="undoEdit" :disabled="!undo.length">Hoàn tác</el-button><el-button size="small" @click="redoEdit" :disabled="!redo.length">Làm lại</el-button><el-button size="small" type="primary" @click="saveEdits">Lưu bản nháp mới</el-button></div><div v-else-if="selectedVersion?.status==='DRAFT'"><el-button size="small" @click="openJob('REPAIR')">Tìm phương án khác</el-button><el-button size="small" @click="refresh()">Từ chối / về lịch áp dụng</el-button><el-button size="small" type="primary" @click="confirmVersion()">Duyệt lịch dự kiến</el-button><el-button size="small" @click="confirmVersion('PUBLISHED')">Công bố</el-button></div></div></section>
 <section v-else class="empty">Chưa có dữ liệu. <el-button @click="importDialog=true">Import Excel</el-button></section>
 </template>
 <section v-if="route.path==='/requests'" class="page-content"><div class="section-heading"><div><h2>Yêu cầu bắt buộc và nguyện vọng mềm</h2><p>APPROVED: đã duyệt. APPLIED: đã được áp dụng trong phiên bản được xác nhận.</p></div><el-button type="primary" @click="newRequest()">Thêm / nhập hàng loạt</el-button></div><el-tabs v-model="requestTab"><el-tab-pane label="Yêu cầu bắt buộc" name="hard"><el-input v-model="requestFilter" placeholder="Lọc tên, mã, lý do…" style="width:320px" clearable/><div class="table-scroll"><table class="data-table"><thead><tr><th>Nhân sự</th><th>Ngày</th><th>Mã</th><th>Trạng thái</th><th>Lý do</th><th>Thao tác</th></tr></thead><tbody><tr v-for="r in requestRows.filter(r=>`${employeeName(r.employee_id)} ${r.code} ${r.reason}`.toLowerCase().includes(requestFilter.toLowerCase()))" :key="r.id"><td>{{employeeName(r.employee_id)}} <small>#{{r.employee_id}}</small></td><td>{{r.day}}</td><td :class="'code-'+r.code">{{r.code}}</td><td><span class="status-tag">{{r.status}}</span></td><td>{{r.reason}}</td><td><el-button size="small" v-if="r.status==='DRAFT'" @click="transition(r,'SUBMITTED')">Gửi duyệt</el-button><el-button size="small" v-if="r.status==='SUBMITTED'" @click="transition(r,'APPROVED')">Duyệt</el-button><el-button size="small" v-if="!['CANCELLED','REJECTED'].includes(r.status)" @click="transition(r,'CANCELLED')">Hủy</el-button><el-button size="small" v-if="!['CANCELLED','REJECTED'].includes(r.status)" @click="newRequest(r.employee_id,r.day);requestForm.replace_ids=[r.id]">Thay thế</el-button></td></tr></tbody></table></div></el-tab-pane><el-tab-pane label="Nguyện vọng mềm" name="soft"><div class="inline-form"><el-select v-model="preferenceForm.employee_id" filterable placeholder="Nhân sự"><el-option v-for="e in store.calendar?.employees" :key="e.id" :value="e.id" :label="e.name"/></el-select><input type="date" v-model="preferenceForm.day"/><el-select v-model="preferenceForm.kind"><el-option v-for="(label,key) in {PREFER_OFF:'Muốn nghỉ OFF',PREFER_WORK:'Muốn đi ca',PREFER_SHIFT:'Muốn ca cụ thể',AVOID_SHIFT:'Tránh ca cụ thể'}" :key="key" :value="key" :label="label"/></el-select><el-input-number v-if="['PREFER_SHIFT','AVOID_SHIFT'].includes(preferenceForm.kind)" v-model="preferenceForm.shift" :min="1" :max="3"/><label>Trọng số<el-input-number v-model="preferenceForm.weight" :min="1" :max="10"/></label><el-button type="primary" @click="savePreference">Lưu</el-button></div><el-table :data="prefs"><el-table-column prop="employee_id" label="ID"/><el-table-column prop="day" label="Ngày"/><el-table-column prop="kind" label="Nguyện vọng"/><el-table-column prop="shift" label="Ca"/><el-table-column prop="weight" label="Trọng số"/></el-table></el-tab-pane></el-tabs></section>
 <section v-if="route.path==='/employees'" class="page-content"><div class="section-heading"><div><h2>Nhân sự tháng {{store.calendar?.month.month}}/{{store.calendar?.month.year}}</h2><p>Quyền và vai trò được lưu theo tháng; lịch sử phiên bản giữ nguyên snapshot.</p></div><el-button type="primary" @click="editEmployee()">Thêm nhân sự</el-button></div><table class="data-table"><thead><tr><th>ID</th><th>Họ tên</th><th>Nhóm</th><th>Phụ trách</th><th>Quyền ca</th><th>Công chuẩn</th><th></th></tr></thead><tbody><tr v-for="e in store.calendar?.employees" :key="e.id"><td>{{e.id}}</td><td>{{e.name}}</td><td>{{e.group}}</td><td>{{e.is_leader?'Có':'Không'}}</td><td>{{e.allowed_shifts.join(', ')}}</td><td>{{e.target_credit??'Theo ngày làm việc tháng'}}</td><td><el-button size="small" @click="editEmployee(e)">Chỉnh sửa</el-button></td></tr></tbody></table></section>
 <section v-if="route.path==='/rules'&&rules" class="page-content"><div class="section-heading"><div><h2>Rule profile #{{rules.profile.id}} · revision {{rules.profile.revision}}</h2><p>Chỉ hiển thị tùy chọn mà Solver hiện hỗ trợ. Thay đổi tạo revision mới.</p></div><el-button type="primary" @click="saveRules">Lưu revision quy tắc</el-button></div><div class="rules-grid"><div><h3>Ràng buộc cứng</h3><label v-for="k in hardRuleKeys" :key="k" class="rule-field">{{ruleNames[k]}}<el-input-number v-model="rulesForm[k]" :min="k==='min_rest_hours'?0:1" :max="31"/></label></div><div><h3>Mục tiêu mềm theo thứ tự</h3><label v-for="k in softRuleKeys" :key="k" class="rule-field">{{ruleNames[k]}}<el-switch v-model="rulesForm[k]"/></label></div></div><details><summary>Giải thích nghiệp vụ A/B/C/D và E01–E06</summary><table class="data-table"><tbody><tr v-for="r in rules.catalog.filter((r:any)=>!r.id.startsWith('CFG_')&&r.id!=='REPAIR')" :key="r.id"><th>{{r.id}} · {{r.title}}</th><td>{{r.criterion}}</td></tr></tbody></table></details><h3>Ngày lễ và nhu cầu tháng</h3><div class="rules-grid"><label>Ngày lễ (YYYY-MM-DD, mỗi dòng một ngày)<el-input v-model="holidayText" type="textarea" :rows="5"/></label><label>Giả định dữ liệu<el-input v-model="assumptions" type="textarea" :rows="4"/><el-checkbox v-model="inputConfirmed">Dữ liệu tháng đã được xác nhận</el-checkbox></label></div><details><summary>Nhu cầu từng ngày / ca ({{demandRows.length}} dòng)</summary><table class="data-table"><thead><tr><th>Ngày</th><th>Ca</th><th>Số người</th></tr></thead><tbody><tr v-for="row in demandRows" :key="row.day+'-'+row.shift"><td>{{row.day}}</td><td>{{row.shift}}</td><td><el-input-number v-model="row.count" :min="0" :max="1000" size="small"/></td></tr></tbody></table></details><el-button type="primary" @click="saveCalendar">Lưu cấu hình tháng</el-button></section>
 <section v-if="route.path==='/annual'" class="page-content"><div class="section-heading"><div><h2>Lịch nền năm V0</h2><p>Giải lần lượt từng tháng, truyền lịch sử và kiểm tra biên trước khi lưu toàn bộ.</p></div><div><el-button @click="annualDialog=true">Tạo kế hoạch 12 tháng</el-button><el-button type="primary" @click="openJob('ANNUAL')" :disabled="!planId||!!busyJob||annual?.plan.baseline_frozen">Lập lịch năm</el-button></div></div><el-select v-model="planId" style="width:300px" @change="extras"><el-option v-for="p in plans" :key="p.id" :value="p.id" :label="p.name+' · '+p.status"/></el-select><div v-if="annual" class="annual-months"><button v-for="n in 12" :key="n" :disabled="!annual.months.find((m:any)=>m.month===n)" @click="store.monthId=annual.months.find((m:any)=>m.month===n)?.id;changeMonth();router.push('/')"><strong>Tháng {{String(n).padStart(2,'0')}}</strong><span>{{annual.months.find((m:any)=>m.month===n)?.current_version_id?'Đã có lịch dự kiến':'Chưa xếp lịch'}}</span><small>{{annual.months.find((m:any)=>m.month===n)?.pending_requests??0}} yêu cầu chờ</small></button></div><template v-if="annual"><p class="assumptions">{{annual.plan.assumptions}}</p><div class="section-heading"><h3>Thống kê tích lũy</h3><a :href="`/api/annual-plans/${planId}/export`" class="download-button">Xuất tổng hợp năm</a></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Nhân sự</th><th v-for="c in ['Ca 1','Ca 2','Ca 3','Lễ','Cuối tuần','Nghỉ cuối tuần','Vượt công','Nghỉ ngắn','Ô đổi','Thay người','Lệch V0']" :key="c">{{c}}</th></tr></thead><tbody><tr v-for="e in annual.employees" :key="e.employee_id"><td>{{e.name}}</td><td v-for="k in ['shift_1','shift_2','shift_3','holiday','weekend','full_weekends','overtime','short_rest','changes','substitutions','baseline_differences']" :key="k">{{e[k]}}</td></tr></tbody></table></div><h3>Lịch cá nhân nhiều tháng</h3><el-select v-model="annualEmployee" clearable placeholder="Chọn nhân sự"><el-option v-for="e in annual.employees" :key="e.employee_id" :value="e.employee_id" :label="e.name"/></el-select><a v-if="annualEmployee" class="download-button" :href="`/api/annual-plans/${planId}/export?employee_id=${annualEmployee}`">Xuất lịch cá nhân</a><div v-if="annualEmployee" class="personal-days"><span v-for="d in annual.personal.filter((x:any)=>x.employee_id===annualEmployee)" :key="d.day" :class="'code-'+d.code"><small>{{d.day}}</small>{{d.code==='OFF'?'':d.code}}</span></div></template></section>
 <section v-if="route.path==='/history'" class="page-content"><div class="section-heading"><h2>Phiên bản và lần chạy Solver</h2><el-button @click="validate" :disabled="!versionId">Kiểm tra lịch đang xem</el-button></div><table class="data-table"><thead><tr><th>Phiên bản</th><th>Trạng thái</th><th>Nguồn</th><th>Validator</th><th>Chứng minh</th><th></th></tr></thead><tbody><tr v-for="v in store.calendar?.versions" :key="v.id"><td>{{v.id.slice(0,8)}}<small>{{v.created_at}}</small></td><td>{{v.status}}</td><td>{{v.source}}</td><td>{{v.validation_status}}</td><td>{{v.proof.status}}</td><td><el-button size="small" @click="refresh(v.id);router.push('/')">Xem lịch</el-button><el-button size="small" @click="act(()=>post(`/versions/${v.id}/restore`,{revision:store.revision}),'Đã tạo phiên bản con').then(r=>r&&refresh(r.version_id))">Khôi phục thành nháp</el-button></td></tr></tbody></table><h3>Lần chạy</h3><table class="data-table"><thead><tr><th>Job</th><th>Chế độ</th><th>Trạng thái</th><th>Thời gian</th><th></th></tr></thead><tbody><tr v-for="j in store.jobs" :key="j.id"><td>{{j.id.slice(0,8)}}</td><td>{{j.mode}}</td><td>{{j.status}}</td><td>{{j.created_at}}</td><td><el-button size="small" @click="jobDetail=j;jobLogDialog=true">Chi tiết</el-button></td></tr></tbody></table><details><summary>Nhật ký thay đổi</summary><table class="data-table"><tbody><tr v-for="a in audit" :key="a.id"><td>{{a.created_at}}</td><td>{{a.action}}</td><td>{{a.entity_id}}</td></tr></tbody></table></details></section>
 </main>
</div>
<el-dialog v-model="cellDialog" :title="`${cell?.employee.name??''} · ${cell?.day.date??''}`" width="500px"><template v-if="cell"><div class="detail-list"><p><strong>Mã lịch:</strong> {{cellCode}} <small v-if="cellCode==='OFF'">(hiển thị trống trên bảng)</small></p><p><strong>Phiên bản:</strong> {{selectedVersion?.status??'Chưa xếp lịch'}}</p><p v-for="r in store.calendar?.requests.filter(r=>r.employee_id===cell!.employee.id&&r.day===cell!.day.date)" :key="r.id"><strong>Yêu cầu {{r.code}} · {{r.status}}</strong><br>{{r.reason}}</p><p v-for="l in store.calendar?.locks.filter(l=>l.employee_id===cell!.employee.id&&l.day===cell!.day.date)" :key="l.day">Khóa: {{l.reason}}</p></div><template v-if="selectedVersion?.status==='DRAFT'"><label>Mã chỉnh sửa (lưu thành bản nháp con)<el-select v-model="cellCode"><el-option v-for="c in ['1','2','3','OFF','CT','DT','BKD','T']" :key="c" :value="c" :label="c"/></el-select></label><el-button @click="editCell">Đưa vào chỉnh sửa</el-button></template></template><template #footer><el-button @click="lockCell(false)">Mở khóa</el-button><el-button @click="lockCell(true)">Khóa ô</el-button><el-button type="primary" @click="cellDialog=false;newRequest(cell?.employee.id,cell?.day.date)">Tạo yêu cầu</el-button></template></el-dialog>
<el-dialog v-model="requestDialog" title="Khai báo yêu cầu / nhập hàng loạt" width="650px"><el-form label-position="top"><el-form-item label="Nhân sự (chọn nhiều người)"><el-select v-model="requestForm.employee_ids" multiple filterable style="width:100%"><el-option v-for="e in store.calendar?.employees" :key="e.id" :value="e.id" :label="`${e.id} · ${e.name}`"/></el-select><div class="selection-tools"><el-button size="small" @click="requestForm.employee_ids=store.calendar?.employees.filter(e=>e.group==='SHIFT').map(e=>e.id)??[]">Chọn nhóm SHIFT</el-button><el-button size="small" @click="requestForm.employee_ids=store.calendar?.employees.filter(e=>e.group==='ADMIN').map(e=>e.id)??[]">Chọn nhóm ADMIN</el-button></div></el-form-item><div class="form-pair"><el-form-item label="Từ ngày"><input type="date" v-model="requestForm.from_date"/></el-form-item><el-form-item label="Đến ngày"><input type="date" v-model="requestForm.to_date"/></el-form-item></div><div class="form-pair"><el-form-item label="Mã yêu cầu"><el-select v-model="requestForm.code"><el-option v-for="c in ['OFF','CT','DT','BKD','1','2','3']" :key="c" :value="c" :label="c"/></el-select></el-form-item><el-form-item label="Trạng thái"><el-select v-model="requestForm.status"><el-option value="APPROVED" label="Đã duyệt, chờ áp dụng"/><el-option value="SUBMITTED" label="Chờ duyệt"/><el-option value="DRAFT" label="Bản nháp"/></el-select></el-form-item></div><el-form-item label="Lý do"><el-input v-model="requestForm.reason" type="textarea" :rows="3"/></el-form-item><p v-if="requestForm.replace_ids.length" class="notice">Đang thay thế {{requestForm.replace_ids.length}} yêu cầu. Yêu cầu cũ sẽ được hủy có lưu lịch sử.</p><p>Yêu cầu mới hiển thị ngay dưới dạng overlay. Lịch áp dụng chỉ thay đổi sau REPAIR và bước duyệt.</p></el-form><template #footer><el-button @click="requestDialog=false">Đóng</el-button><el-button type="primary" @click="saveRequest">Lưu yêu cầu</el-button></template></el-dialog>
<el-dialog v-model="jobDialog" :title="`Chạy ${jobMode}`" width="650px"><el-form label-position="top"><p v-if="jobMode!=='FRESH'&&jobMode!=='ANNUAL'">Lịch tham chiếu: {{versionId.slice(0,8)}} · {{selectedVersion?.status}}</p><div class="form-pair"><el-form-item label="Tổng ngân sách (giây)"><el-input-number v-model="jobForm.budget" :min="1" :max="86400"/></el-form-item><el-form-item v-if="jobMode==='RESUME'" label="Tối đa lượt RESUME (dừng khi 2 lượt không cải thiện)"><el-input-number v-model="jobForm.passes" :min="1" :max="20"/></el-form-item></div><template v-if="jobMode==='REPAIR'"><el-form-item label="Yêu cầu đã duyệt / yêu cầu đã hủy cần áp dụng"><el-select v-model="jobForm.request_ids" multiple style="width:100%"><el-option v-for="r in repairChoices" :key="r.id" :value="r.id" :label="`${employeeName(r.employee_id)} · ${r.day} · ${r.code}`"/></el-select></el-form-item><div class="form-pair"><el-form-item label="Phạm vi tìm kiếm"><el-select v-model="jobForm.repair_mode"><el-option value="FAST" label="FAST · vùng nhỏ đầu tiên"/><el-option value="OPTIMAL" label="OPTIMAL · tiếp tục mở rộng phạm vi"/></el-select></el-form-item><el-form-item label="Thời điểm as_of (+07:00)"><input type="datetime-local" v-model="jobForm.as_of"/></el-form-item></div><div class="form-pair"><el-form-item label="Cho phép sửa từ ngày"><input type="date" v-model="jobForm.allowed_from"/></el-form-item><el-form-item label="Đến ngày"><input type="date" v-model="jobForm.allowed_until"/></el-form-item></div><el-form-item label="Số ô đổi tối đa (để trống = không giới hạn)"><el-input-number v-model="jobForm.max_changes" :min="0" :max="100000"/></el-form-item><el-checkbox v-model="jobForm.no_admin_increase">Không tăng ADMIN</el-checkbox><el-checkbox v-model="jobForm.no_overtime_increase">Không tăng công vượt</el-checkbox><p>Giữ ô khóa, ngày đã thực hiện và ca đã bắt đầu. Ca 1 ngày D bắt đầu 22:00 ngày D−1. Khi thiếu giờ phi ca, khóa bảo thủ từ đầu ngày.</p></template><p v-else-if="jobMode==='FRESH'">{{freshHelp}}</p><p v-else-if="jobMode==='ANNUAL'">Giải Rolling Horizon theo từng tháng. Toàn bộ kết quả và biên tháng phải được kiểm tra trước khi lưu trong cùng transaction. Xác nhận V0 là bước riêng.</p></el-form><template #footer><el-button @click="jobDialog=false">Đóng</el-button><el-button type="primary" @click="runJob">Bắt đầu Solver</el-button></template></el-dialog>
<el-dialog v-model="jobLogDialog" title="Tiến trình và kết quả Solver" width="900px"><template v-if="jobDetail"><div class="detail-list"><p><strong>{{jobDetail.mode}} · {{jobDetail.status}}</strong> · {{jobDetail.stage}}</p><p>Ngân sách {{jobDetail.options.budget}} giây · Bắt đầu {{jobDetail.started_at??'Chưa bắt đầu'}} · Kết thúc {{jobDetail.finished_at??'Đang chạy'}}</p><p v-if="jobDetail.error" class="error-text">{{jobDetail.error}}</p><p v-if="jobDetail.result?.version_ids">{{jobDetail.result.version_ids.length}} bản nháp đã được lưu; chưa tự công bố.</p><div v-if="jobDetail.result?.repair" class="repair-summary"><strong>{{jobDetail.result.repair.changed_cells}} ô thay đổi · {{jobDetail.result.repair.affected_people}} nhân sự</strong><p>Vector REPAIR: {{JSON.stringify(jobDetail.result.repair.vector.slice(0,7))}}</p><p>Công trước: {{JSON.stringify(jobDetail.result.repair.work_before)}}</p><p>Công sau: {{JSON.stringify(jobDetail.result.repair.work_after)}}</p></div><pre class="solver-log">{{jobDetail.log||'Chờ log từ worker…'}}</pre></div></template><template #footer><el-button @click="jobLogDialog=false">Đóng</el-button><el-button v-if="jobDetail?.result?.version_ids?.length===1" type="primary" @click="jobLogDialog=false;viewResult(jobDetail)">Xem lịch và so sánh</el-button><el-button v-if="jobDetail?.mode==='ANNUAL'&&jobDetail.status==='SUCCEEDED'" type="primary" @click="acceptAnnual(jobDetail)">Duyệt toàn bộ V0 dự kiến</el-button></template></el-dialog>
<el-dialog v-model="validationDialog" title="Independent Validator — kiểm tra snapshot" width="1050px"><template v-if="validation"><p><strong>{{validation.verdict}}</strong> · {{validation.errors}} lỗi cứng · {{validation.warnings}} cảnh báo · Chứng minh: {{validation.proof.status}}</p><p v-if="validation.hard_pending?.length" class="notice">NOT_CHECKED: {{validation.hard_pending.join(', ')}}. Chưa được coi là hợp lệ hoàn toàn.</p><p>Biên tháng đã cung cấp: {{validation.boundaries?.length??0}}. Lịch sử E05 thiếu: {{validation.history_gaps}} ô.</p><div class="table-scroll validation-table"><table class="data-table"><thead><tr><th>Rule</th><th>Trạng thái</th><th>Điểm / ghi chú</th><th>Chi tiết</th></tr></thead><tbody><tr v-for="r in validation.rules" :key="r.rule_id"><th>{{r.rule_id}}</th><td :class="r.status==='FAIL'?'error-text':''">{{r.status}}</td><td>{{r.score??''}} {{r.note}}</td><td><button class="text-button" v-for="(f,index) in r.findings" :key="index" @click="validationDialog=false;search=employeeName(f.employee_id);router.push('/')">{{f.severity}} · ID {{f.employee_id}} {{f.day}}: {{f.message}}</button></td></tr></tbody></table></div></template></el-dialog>
<el-dialog v-model="employeesDialog" title="Nhân sự và quyền ca trong tháng" width="550px"><el-form label-position="top"><div class="form-pair"><el-form-item label="ID"><el-input-number v-model="employeeForm.id" :min="1"/></el-form-item><el-form-item label="Nhóm"><el-select v-model="employeeForm.group"><el-option value="SHIFT" label="SHIFT"/><el-option value="ADMIN" label="ADMIN"/></el-select></el-form-item></div><el-form-item label="Họ tên"><el-input v-model="employeeForm.name"/></el-form-item><el-checkbox v-model="employeeForm.is_leader">Phụ trách ca</el-checkbox><el-form-item label="Quyền đi ca"><el-checkbox-group v-model="employeeForm.allowed_shifts"><el-checkbox :value="1">Ca 1</el-checkbox><el-checkbox :value="2">Ca 2</el-checkbox><el-checkbox :value="3">Ca 3</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="Công chuẩn riêng (trống = theo lịch tháng)"><el-input-number v-model="employeeForm.target_credit" :min="0"/></el-form-item></el-form><template #footer><el-button type="primary" @click="saveEmployee">Lưu cho tháng đang chọn</el-button></template></el-dialog>
<el-dialog v-model="workTimeDialog" title="Giờ phi ca — chỉ phục vụ Validator" width="620px"><p>Không tự áp ngưỡng 8 giờ. Nhập ngưỡng nghiệp vụ đã được xác nhận. Solver chưa hỗ trợ các ràng buộc giờ phi ca; phương án vi phạm sẽ bị từ chối trước khi lưu.</p><label>Ngưỡng nghỉ phi ca đã xác nhận (giờ)<el-input-number v-model="workTimeRest" :min="0" :max="24" :step="0.5"/></label><table class="data-table"><thead><tr><th>Mã làm việc</th><th>Bắt đầu</th><th>Kết thúc</th></tr></thead><tbody><tr v-for="row in workTimes" :key="row.code"><td>{{row.code}}</td><td><input type="time" v-model="row.start"/></td><td><input type="time" v-model="row.end"/></td></tr><tr><td>BKD</td><td colspan="2">Không làm việc</td></tr></tbody></table><p>Để trống mã chưa biết giờ thì kiểm tra vẫn INCOMPLETE. Không thay đổi snapshot cũ.</p><template #footer><el-button @click="workTimeDialog=false">Đóng</el-button><el-button type="primary" @click="saveWorkTimes">Lưu revision kiểm tra</el-button></template></el-dialog>
<el-dialog v-model="annualDialog" title="Tạo đầu vào kế hoạch 12 tháng" width="600px"><el-form label-position="top"><el-form-item label="Năm"><el-input-number v-model="annualForm.year" :min="1900" :max="2200"/></el-form-item><el-form-item label="Tên kế hoạch"><el-input v-model="annualForm.name"/></el-form-item><el-form-item label="Giả định dữ liệu tương lai (bắt buộc)"><el-input v-model="annualForm.assumptions" type="textarea" :rows="4"/></el-form-item><p>Tháng đầu phải nối tiếp lịch nguồn có đủ ít nhất 6 ngày lịch sử. Có thể điều chỉnh ngày lễ, nhu cầu và nhân sự từng tháng trước khi chạy.</p></el-form><template #footer><el-button type="primary" @click="createAnnual">Tạo kế hoạch</el-button></template></el-dialog>
<el-dialog v-model="importDialog" title="Import dữ liệu AutoShift cũ" width="700px"><el-form label-position="top"><el-form-item label="Đường dẫn input.xlsx"><el-input v-model="importForm.excel"/></el-form-item><el-form-item label="Đường dẫn rules.json"><el-input v-model="importForm.rules"/></el-form-item><el-form-item label="Đường dẫn lịch Excel có sheet Schedule (tùy chọn)"><el-input v-model="importForm.schedule"/></el-form-item><el-checkbox v-model="importForm.dry_run">Dry-run: kiểm tra rồi rollback, không lưu</el-checkbox></el-form><pre v-if="importResult" class="solver-log">{{JSON.stringify({...importResult,source_rows:undefined},null,2)}}</pre><template #footer><el-button type="primary" @click="importLegacy">{{importForm.dry_run?'Kiểm tra import':'Import vào SQLite'}}</el-button></template></el-dialog>
</template>
